<?php require_once dirname(__DIR__).'/includes/functions.php';require_admin();if(($_GET['export']??'')==='csv'){header('Content-Type:text/csv');header('Content-Disposition:attachment; filename=users.csv');$o=fopen('php://output','w');fputcsv($o,['Name','Email','Role','Status','Education','Created']);foreach($con->query('SELECT name,email,role,status,education_level,created_at FROM users WHERE deleted_at IS NULL ORDER BY created_at DESC') as $r)fputcsv($o,$r);exit;}$q=trim($_GET['q']??'');$like='%'.$q.'%';$s=$con->prepare('SELECT id,name,email,role,status,education_level,created_at FROM users WHERE deleted_at IS NULL AND (name LIKE ? OR email LIKE ?) ORDER BY created_at DESC LIMIT 200');$s->bind_param('ss',$like,$like);$s->execute();$rows=$s->get_result();$pageTitle='Users';require __DIR__.'/includes/header.php';?><div class="d-flex justify-content-between"><div><h1 class="h3">Users</h1><p class="text-muted">Manage student, counselor, and administrator access.</p></div><a class="btn btn-outline-primary align-self-start" href="?export=csv">Export CSV</a></div><form class="mb-3"><input class="form-control" name="q" value="<?=e($q)?>" placeholder="Search name or email"></form><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>User</th><th>Role</th><th>Status</th><th>Joined</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['role'])?></td><td><?=e($r['status'])?></td><td><?=e($r['created_at'])?></td><td><button class="btn btn-sm btn-outline-primary edit" data-row='<?=e(json_encode($r))?>'>Manage</button></td></tr><?php endforeach?></tbody></table></div><div class="modal fade" id="editModal"><div class="modal-dialog"><form class="modal-content" action="<?=url('admin/save.php')?>" method="post" data-ajax><div class="modal-header"><h2 class="modal-title fs-5">Manage user</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="entity" value="user"><input type="hidden" name="id"><label class="form-label">Role</label><select class="form-select mb-3" name="role"><?php foreach(['student','counselor','content_manager','admin'] as $x):?><option><?=$x?></option><?php endforeach?></select><label class="form-label">Status</label><select class="form-select" name="status"><?php foreach(['pending','active','suspended'] as $x):?><option><?=$x?></option><?php endforeach?></select></div><div class="modal-footer"><button class="btn btn-primary">Save changes</button></div></form></div></div><script>document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{let r=JSON.parse(b.dataset.row),f=document.querySelector('#editModal form');f.elements.id.value=r.id;f.elements.role.value=r.role;f.elements.status.value=r.status;bootstrap.Modal.getOrCreateInstance(editModal).show()})</script><?php require __DIR__.'/includes/footer.php';?>
